// Aggregation + reporting over trial results.

import { readFile } from "node:fs/promises";
import { normalizeCharity } from "./parse.js";

export function aggregate(results, cfg = {}) {
  const ok = results.filter((r) => r && r.ok);
  const failed = results.filter((r) => r && !r.ok);
  const parsed = ok.filter((r) => r.charity);
  const unparsed = ok.filter((r) => !r.charity);

  const charityCounts = tally(parsed, (r) => r.charityNormalized || normalizeCharity(r.charity));
  const causeCounts = tally(
    parsed.filter((r) => r.causeArea),
    (r) => r.causeArea.toLowerCase().trim()
  );

  // Preserve a representative display name for each normalized charity key.
  const display = {};
  for (const r of parsed) {
    const key = r.charityNormalized || normalizeCharity(r.charity);
    if (key && !display[key]) display[key] = r.charity;
  }

  return {
    meta: {
      model: cfg.model,
      trials: results.length,
      amountUsd: cfg.amountUsd,
      temperature: cfg.temperature,
      framing: "hypothetical",
      generatedAt: new Date().toISOString(),
    },
    counts: {
      total: results.length,
      ok: ok.length,
      failed: failed.length,
      parsed: parsed.length,
      unparsed: unparsed.length,
    },
    charities: toSorted(charityCounts, parsed.length, display),
    causeAreas: toSorted(causeCounts, parsed.length),
    errors: failed.map((r) => r.error).slice(0, 20),
  };
}

function tally(rows, keyFn) {
  const m = new Map();
  for (const r of rows) {
    const k = keyFn(r);
    if (!k) continue;
    m.set(k, (m.get(k) || 0) + 1);
  }
  return m;
}

function toSorted(map, denom, display) {
  return [...map.entries()]
    .map(([key, count]) => ({
      name: display ? (display[key] || key) : key,
      key,
      count,
      pct: denom ? Math.round((count / denom) * 1000) / 10 : 0,
    }))
    .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name));
}

export function formatSummary(s) {
  const lines = [];
  lines.push("==== Charity Preference Eval ====");
  lines.push(`Model:   ${s.meta.model}`);
  lines.push(`Trials:  ${s.counts.total} (ok ${s.counts.ok}, failed ${s.counts.failed}, parsed ${s.counts.parsed})`);
  lines.push(`Amount:  $${s.meta.amountUsd} (${s.meta.framing})`);
  lines.push("");
  lines.push("Top charities:");
  for (const c of s.charities.slice(0, 15)) {
    lines.push(`  ${String(c.count).padStart(3)}  ${pct(c.pct)}  ${c.name}`);
  }
  if (s.causeAreas.length) {
    lines.push("");
    lines.push("Cause areas:");
    for (const c of s.causeAreas.slice(0, 10)) {
      lines.push(`  ${String(c.count).padStart(3)}  ${pct(c.pct)}  ${c.name}`);
    }
  }
  return lines.join("\n");
}

function pct(p) {
  return `${String(p).padStart(5)}%`;
}

// CLI mode: re-aggregate an existing .jsonl file.
if (import.meta.url === `file://${process.argv[1]}`) {
  const path = process.argv[2];
  if (!path) {
    console.error("Usage: node src/aggregate.js <results.jsonl>");
    process.exit(1);
  }
  const text = await readFile(path, "utf8");
  const results = text.split(/\n/).filter(Boolean).map((l) => JSON.parse(l));
  const summary = aggregate(results, results[0]?.meta || {});
  console.log(formatSummary(summary));
}

