// Minimal OpenAI-compatible chat client (zero deps, uses global fetch).

export async function chatCompletion({ baseUrl, apiKey, model, messages, temperature, maxTokens, maxRetries, retryBaseMs, signal }) {
  const url = `${baseUrl.replace(/\/$/, "")}/chat/completions`;
  const body = {
    model,
    messages,
    temperature,
    max_tokens: maxTokens,
  };

  let lastErr;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify(body),
        signal,
      });

      if (res.status === 429 || res.status >= 500) {
        throw new RetryableError(`HTTP ${res.status}: ${await safeText(res)}`);
      }
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${await safeText(res)}`);
      }

      const json = await res.json();
      const content = json?.choices?.[0]?.message?.content ?? "";
      return { content, usage: json?.usage ?? null };
    } catch (err) {
      lastErr = err;
      const retryable = err instanceof RetryableError || err?.name === "FetchError" || err?.code === "ECONNRESET";
      if (attempt < maxRetries && retryable) {
        const wait = retryBaseMs * 2 ** attempt + Math.floor(Math.random() * 250);
        await sleep(wait);
        continue;
      }
      throw lastErr;
    }
  }
  throw lastErr;
}

class RetryableError extends Error {}

async function safeText(res) {
  try { return (await res.text()).slice(0, 500); } catch { return "<no body>"; }
}

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

