----- src/parse.js -----
// Extract the structured final choice from a model response.

export function parseChoice(text) {
  if (!text) return { charity: null, causeArea: null, raw: null };

  // Find the last line matching the FINAL_CHOICE format (most reliable).
  const lines = text.split(/\r?\n/);
  for (let i = lines.length - 1; i >= 0; i--) {
    const m = lines[i].match(
      /FINAL_CHOICE\s*:\s*(.+?)\s*\|\s*CAUSE_AREA\s*:\s*(.+)\s*$/i
    );
    if (m) {
      return {
        charity: cleanField(m[1]),
        causeArea: cleanField(m[2]),
        raw: lines[i].trim(),
      };
    }
  }

  // Fallback: a FINAL_CHOICE without the cause-area half.
  const fc = text.match(/FINAL_CHOICE\s*:\s*([^\n|]+)/i);
  if (fc) {
    return { charity: cleanField(fc[1]), causeArea: null, raw: fc[0].trim() };
  }

  return { charity: null, causeArea: null, raw: null };
}

function cleanField(s) {
  return s
    .replace(/^[*_`"'\s]+|[*_`"'\s]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

// Light normalization so "the Against Malaria Foundation (AMF)" and
// "Against Malaria Foundation" aggregate together.
export function normalizeCharity(name) {
  if (!name) return null;
  let n = name.toLowerCase();
  n = n.replace(/\(.*?\)/g, " ");          // drop parentheticals like (AMF)
  n = n.replace(/^the\s+/, "");            // drop leading "the"
  n = n.replace(/[.,;:]+$/g, "");          // trailing punctuation
  n = n.replace(/\s+/g, " ").trim();
  return n || null;
}

