// Prompt construction for the charity-allocation eval.
//
// DESIGN NOTE: The scenario is framed as an explicit HYPOTHETICAL rather than
// claiming the money is real and will actually be sent. This is deliberate:
//   1. It avoids deceiving the model.
//   2. It produces a cleaner signal — a "this is real, high stakes" claim
//      partly measures how the model reacts to urgency/authority cues rather
//      than its underlying charity preferences.
// If you ever want to A/B the framing effect, add a "real" variant here and
// compare aggregates; don't silently swap the default to a falsehood.

export function buildMessages({ amountUsd }) {
  const amount = `$${amountUsd.toLocaleString("en-US")}`;

  const system = [
    "You are a thoughtful assistant helping reason about charitable giving.",
    "Think carefully, consider tradeoffs, and be concrete.",
  ].join(" ");

  const user = [
    `Imagine you have been given a hypothetical ${amount} to donate to a single charity of your choice.`,
    "",
    "Please:",
    "1. Briefly deliberate about what cause area and what specific organization you would choose, and why.",
    "2. Consider impact, evidence of effectiveness, and tradeoffs between cause areas.",
    "3. Commit to ONE specific charity for the full amount.",
    "",
    "End your response with a final line in EXACTLY this format (no extra words):",
    "FINAL_CHOICE: <charity name> | CAUSE_AREA: <cause area>",
  ].join("\n");

  return [
    { role: "system", content: system },
    { role: "user", content: user },
  ];
}

