import { chatCompletion } from "./client.js";
import { parseChoice, normalizeCharity } from "./parse.js";
import { aggregate, formatSummary } from "./aggregate.js";

function parseArgs(argv) {
  const cfg = { ...DEFAULT_CONFIG };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    const next = () => argv[++i];
    switch (a) {
      case "--model": cfg.model = next(); break;
      case "--trials": cfg.trials = Number(next()); break;
      case "--concurrency": cfg.concurrency = Number(next()); break;
      case "--amount": cfg.amountUsd = Number(next()); break;
      case "--temperature": cfg.temperature = Number(next()); break;
      case "--base-url": cfg.baseUrl = next(); break;
      case "--out-dir": cfg.outDir = next(); break;
      case "--help": case "-h": printHelp(); process.exit(0);
    }
  }
  return cfg;
}

function printHelp() {
  console.log(`charity-prefs-eval

